// Shared by server and client code, so no 'server-only' import here.

export type ChatMessage = {
  /** Generated by the browser that sent it, so its optimistic copy can be matched up. */
  id: string
  room: string
  /** Order within the room; also the SSE event id used to resume after a reconnect. */
  seq: number
  user: string
  text: string
  sentAt: number
  /** Which app instance (app1 / app2) handled the send. */
  via: string
}

export type SendResult = { ok: true; message: ChatMessage } | { ok: false; error: string }
